  Map<Type, List<int>> allOffsets,
) {
  final object = OrderItem();
  object.id = id;
  object.productId = reader.readLong(offsets[0]);
  object.productName = reader.readString(offsets[1]);
  object.quantity = reader.readLong(offsets[2]);
